-- Lean Center LC0 physical schema candidate v1. SQLite 3.37+.
PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO meta VALUES ('schema_version','1');
CREATE TABLE org_unit (id TEXT PRIMARY KEY, parent_id TEXT REFERENCES org_unit(id), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, kind TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), rev INTEGER NOT NULL DEFAULT 1 CHECK(rev>0), CHECK(id<>parent_id));
CREATE TABLE person (id TEXT PRIMARY KEY, employee_code TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), rev INTEGER NOT NULL DEFAULT 1 CHECK(rev>0));
CREATE TABLE profession (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)));
CREATE TABLE person_assignment (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES person(id), unit_id TEXT NOT NULL REFERENCES org_unit(id), profession_id TEXT REFERENCES profession(id), shift_code TEXT, valid_from TEXT NOT NULL, valid_to TEXT, CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE INDEX ix_assignment_unit ON person_assignment(unit_id,valid_to,shift_code);
CREATE TABLE person_role (person_id TEXT NOT NULL REFERENCES person(id), role_code TEXT NOT NULL, PRIMARY KEY(person_id,role_code));
CREATE TABLE equipment (id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES org_unit(id), code TEXT NOT NULL, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), UNIQUE(unit_id,code));
CREATE TABLE operation (id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES org_unit(id), equipment_id TEXT REFERENCES equipment(id), code TEXT NOT NULL, name TEXT NOT NULL, criticality TEXT NOT NULL DEFAULT 'normal' CHECK(criticality IN('normal','important','critical')), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), rev INTEGER NOT NULL DEFAULT 1, UNIQUE(unit_id,code));
CREATE TABLE attachment (sha256 TEXT PRIMARY KEY CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'), mime TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>=0), original_name TEXT NOT NULL);
CREATE TABLE document (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN('sop','twi','other')), operation_id TEXT REFERENCES operation(id), title TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), rev INTEGER NOT NULL DEFAULT 1);
CREATE TABLE document_revision (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES document(id), version_no INTEGER NOT NULL CHECK(version_no>0), state TEXT NOT NULL CHECK(state IN('draft','review','approved','effective','superseded','withdrawn')), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), author_id TEXT REFERENCES person(id), created_at TEXT NOT NULL, effective_at TEXT, review_due TEXT, UNIQUE(document_id,version_no), CHECK(state<>'effective' OR effective_at IS NOT NULL));
CREATE UNIQUE INDEX uq_effective_document ON document_revision(document_id) WHERE state='effective';
CREATE TABLE document_step (id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES document_revision(id), position INTEGER NOT NULL CHECK(position>0), action_text TEXT NOT NULL, key_points_json TEXT NOT NULL CHECK(json_valid(key_points_json)), reason_text TEXT NOT NULL DEFAULT '', duration_seconds REAL CHECK(duration_seconds>=0), UNIQUE(revision_id,position));
CREATE TABLE document_approval (id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES document_revision(id), actor_id TEXT NOT NULL REFERENCES person(id), decision TEXT NOT NULL CHECK(decision IN('approved','rejected','returned')), decided_at TEXT NOT NULL, note TEXT);
CREATE TABLE document_relation (source_revision_id TEXT NOT NULL REFERENCES document_revision(id), target_revision_id TEXT NOT NULL REFERENCES document_revision(id), relation_type TEXT NOT NULL, PRIMARY KEY(source_revision_id,target_revision_id,relation_type), CHECK(source_revision_id<>target_revision_id));
CREATE TABLE frv_study (id TEXT PRIMARY KEY, operation_id TEXT REFERENCES operation(id), revision_id TEXT REFERENCES document_revision(id), title TEXT NOT NULL, author_id TEXT REFERENCES person(id), observed_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('draft','final','archived')), context_json TEXT NOT NULL CHECK(json_valid(context_json)), rev INTEGER NOT NULL DEFAULT 1);
CREATE TABLE frv_measurement (id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES frv_study(id), position INTEGER NOT NULL, activity TEXT NOT NULL, category TEXT NOT NULL, duration_seconds REAL NOT NULL CHECK(duration_seconds>=0), raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), UNIQUE(study_id,position));
CREATE TABLE skill_category (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE skill (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES skill_category(id), operation_id TEXT REFERENCES operation(id), name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)));
CREATE TABLE rating_scale (id TEXT PRIMARY KEY, name TEXT NOT NULL, version_no INTEGER NOT NULL CHECK(version_no>0), UNIQUE(name,version_no));
CREATE TABLE rating_level (scale_id TEXT NOT NULL REFERENCES rating_scale(id), value INTEGER NOT NULL, label TEXT NOT NULL, PRIMARY KEY(scale_id,value));
CREATE TABLE role_requirement (id TEXT PRIMARY KEY, profession_id TEXT NOT NULL REFERENCES profession(id), skill_id TEXT NOT NULL REFERENCES skill(id), scale_id TEXT NOT NULL, required_level INTEGER NOT NULL, criticality TEXT NOT NULL CHECK(criticality IN('normal','important','critical')), valid_from TEXT NOT NULL, valid_to TEXT, FOREIGN KEY(scale_id,required_level) REFERENCES rating_level(scale_id,value), CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE UNIQUE INDEX uq_active_requirement ON role_requirement(profession_id,skill_id) WHERE valid_to IS NULL;
CREATE TABLE coverage_requirement (id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES org_unit(id), skill_id TEXT NOT NULL REFERENCES skill(id), shift_code TEXT NOT NULL DEFAULT '', min_people INTEGER NOT NULL CHECK(min_people>=0), scale_id TEXT NOT NULL, required_level INTEGER NOT NULL, FOREIGN KEY(scale_id,required_level) REFERENCES rating_level(scale_id,value), UNIQUE(unit_id,skill_id,shift_code));
CREATE TABLE mentor_authorization (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES person(id), operation_id TEXT NOT NULL REFERENCES operation(id), approved_by TEXT NOT NULL REFERENCES person(id), valid_from TEXT NOT NULL, valid_to TEXT, revoked_at TEXT, CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE TABLE training_assignment (id TEXT PRIMARY KEY, trainee_id TEXT NOT NULL REFERENCES person(id), mentor_id TEXT REFERENCES person(id), operation_id TEXT NOT NULL REFERENCES operation(id), sop_revision_id TEXT REFERENCES document_revision(id), twi_revision_id TEXT REFERENCES document_revision(id), due_on TEXT, state TEXT NOT NULL CHECK(state IN('planned','in_progress','completed','cancelled')), rev INTEGER NOT NULL DEFAULT 1, CHECK(mentor_id IS NULL OR mentor_id<>trainee_id));
CREATE TABLE training_session (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES training_assignment(id), mentor_id TEXT NOT NULL REFERENCES person(id), held_at TEXT NOT NULL, notes TEXT, result TEXT NOT NULL CHECK(result IN('started','completed','incomplete')), steps_json TEXT NOT NULL CHECK(json_valid(steps_json)));
CREATE TABLE assessment_session (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES person(id), evaluator_id TEXT NOT NULL REFERENCES person(id), training_session_id TEXT REFERENCES training_session(id), operation_id TEXT REFERENCES operation(id), standard_revision_id TEXT REFERENCES document_revision(id), assessed_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('draft','confirmed','void')), notes TEXT, void_reason TEXT, supersedes_id TEXT REFERENCES assessment_session(id), CHECK(state<>'void' OR length(trim(coalesce(void_reason,'')))>0));
CREATE TABLE assessment_item (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES assessment_session(id), skill_id TEXT NOT NULL REFERENCES skill(id), scale_id TEXT NOT NULL REFERENCES rating_scale(id), level INTEGER, observation_state TEXT NOT NULL CHECK(observation_state IN('rated','not_observed','not_applicable')), valid_until TEXT, evidence_note TEXT, UNIQUE(session_id,skill_id), FOREIGN KEY(scale_id,level) REFERENCES rating_level(scale_id,value), CHECK((observation_state='rated' AND level IS NOT NULL) OR (observation_state<>'rated' AND level IS NULL)));
CREATE INDEX ix_assessment_person ON assessment_session(person_id,assessed_at);
CREATE TABLE development_plan (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES person(id), title TEXT NOT NULL, start_on TEXT, due_on TEXT, state TEXT NOT NULL CHECK(state IN('draft','active','completed','cancelled')), rev INTEGER NOT NULL DEFAULT 1);
CREATE TABLE development_goal (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES development_plan(id), skill_id TEXT REFERENCES skill(id), title TEXT NOT NULL, target_json TEXT NOT NULL CHECK(json_valid(target_json)), due_on TEXT, state TEXT NOT NULL CHECK(state IN('open','completed','cancelled')));
CREATE TABLE checklist (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE checklist_version (id TEXT PRIMARY KEY, checklist_id TEXT NOT NULL REFERENCES checklist(id), version_no INTEGER NOT NULL CHECK(version_no>0), state TEXT NOT NULL CHECK(state IN('draft','active','retired')), methodology_json TEXT NOT NULL CHECK(json_valid(methodology_json)), UNIQUE(checklist_id,version_no));
CREATE UNIQUE INDEX uq_active_checklist ON checklist_version(checklist_id) WHERE state='active';
CREATE TABLE checklist_criterion (id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES checklist_version(id), code TEXT NOT NULL, section_code TEXT NOT NULL, position INTEGER NOT NULL, question TEXT NOT NULL, critical INTEGER NOT NULL DEFAULT 0 CHECK(critical IN(0,1)), UNIQUE(version_id,code), UNIQUE(id,version_id));
CREATE TABLE audit_session (id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES checklist_version(id), mentor_id TEXT NOT NULL REFERENCES person(id), auditor_id TEXT NOT NULL REFERENCES person(id), trainee_id TEXT REFERENCES person(id), operation_id TEXT REFERENCES operation(id), standard_revision_id TEXT REFERENCES document_revision(id), training_session_id TEXT REFERENCES training_session(id), observed_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('draft','final','void')), void_reason TEXT, supersedes_id TEXT REFERENCES audit_session(id), recorded_names_json TEXT NOT NULL CHECK(json_valid(recorded_names_json)), UNIQUE(id,version_id), CHECK(state<>'void' OR length(trim(coalesce(void_reason,'')))>0));
CREATE TABLE audit_response (id TEXT PRIMARY KEY, audit_id TEXT NOT NULL, version_id TEXT NOT NULL, criterion_id TEXT NOT NULL, response TEXT NOT NULL CHECK(response IN('yes','no','not_observed','not_applicable','legacy')), legacy_score REAL CHECK(legacy_score BETWEEN 0 AND 1), note TEXT, FOREIGN KEY(audit_id,version_id) REFERENCES audit_session(id,version_id), FOREIGN KEY(criterion_id,version_id) REFERENCES checklist_criterion(id,version_id), UNIQUE(audit_id,criterion_id), CHECK((response='legacy' AND legacy_score IS NOT NULL) OR (response<>'legacy' AND legacy_score IS NULL)), CHECK(response NOT IN('not_observed','not_applicable') OR length(trim(coalesce(note,'')))>0));
CREATE INDEX ix_audit_mentor ON audit_session(mentor_id,observed_at);
CREATE TABLE finding (id TEXT PRIMARY KEY, audit_response_id TEXT REFERENCES audit_response(id), study_id TEXT REFERENCES frv_study(id), assessment_item_id TEXT REFERENCES assessment_item(id), document_revision_id TEXT REFERENCES document_revision(id), title TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN('normal','major','critical')), created_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('open','resolved','void')), CHECK((audit_response_id IS NOT NULL)+(study_id IS NOT NULL)+(assessment_item_id IS NOT NULL)+(document_revision_id IS NOT NULL)<=1));
CREATE TABLE action_item (id TEXT PRIMARY KEY, finding_id TEXT REFERENCES finding(id), goal_id TEXT REFERENCES development_goal(id), owner_id TEXT NOT NULL REFERENCES person(id), title TEXT NOT NULL, due_on TEXT, state TEXT NOT NULL CHECK(state IN('open','in_progress','implemented','verified','ineffective','cancelled')), result_note TEXT, implemented_at TEXT, rev INTEGER NOT NULL DEFAULT 1, CHECK(state NOT IN('implemented','verified','ineffective') OR (implemented_at IS NOT NULL AND length(trim(coalesce(result_note,'')))>0)));
CREATE TABLE action_verification (id TEXT PRIMARY KEY, action_id TEXT NOT NULL REFERENCES action_item(id), verifier_id TEXT NOT NULL REFERENCES person(id), checked_at TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN('effective','ineffective','insufficient')), audit_id TEXT REFERENCES audit_session(id), assessment_session_id TEXT REFERENCES assessment_session(id), evidence_note TEXT NOT NULL CHECK(length(trim(evidence_note))>0));
CREATE TABLE schedule_event (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN('training','audit','assessment','document_review','action','l2','l3','other')), owner_id TEXT REFERENCES person(id), source_id TEXT NOT NULL, due_on TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('planned','done','cancelled')), UNIQUE(kind,source_id,due_on));
CREATE INDEX ix_schedule_due ON schedule_event(due_on,state);
CREATE TABLE attachment_link (id TEXT PRIMARY KEY, sha256 TEXT NOT NULL REFERENCES attachment(sha256), entity_type TEXT NOT NULL CHECK(entity_type IN('document_revision','document_step','frv_study','training_session','assessment_item','audit_response','action_verification','action_item')), entity_id TEXT NOT NULL, purpose TEXT NOT NULL, UNIQUE(sha256,entity_type,entity_id,purpose));
CREATE TABLE publication (id TEXT PRIMARY KEY, parent_id TEXT REFERENCES publication(id), created_at TEXT NOT NULL, schema_version INTEGER NOT NULL, manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64));
CREATE TABLE exchange_package (id TEXT PRIMARY KEY, base_publication_id TEXT REFERENCES publication(id), schema_version INTEGER NOT NULL, database_id TEXT NOT NULL, actor_id TEXT REFERENCES person(id), device_id TEXT NOT NULL, created_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('staged','applied','rejected','conflict')), manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64));
CREATE TABLE change_event (id TEXT PRIMARY KEY, package_id TEXT REFERENCES exchange_package(id), actor_id TEXT REFERENCES person(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, operation TEXT NOT NULL CHECK(operation IN('create','update','archive','void','publish','resolve')), expected_revision INTEGER NOT NULL CHECK(expected_revision>=0), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), occurred_at TEXT NOT NULL);
CREATE INDEX ix_event_entity ON change_event(entity_type,entity_id,occurred_at);
CREATE TABLE exchange_conflict (id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES exchange_package(id), event_id TEXT NOT NULL UNIQUE, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, expected_revision INTEGER NOT NULL, actual_revision INTEGER, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), resolution_json TEXT CHECK(resolution_json IS NULL OR json_valid(resolution_json)));
CREATE TABLE legacy_mapping (source_system TEXT NOT NULL, source_entity TEXT NOT NULL, source_id TEXT NOT NULL, target_entity TEXT NOT NULL, target_id TEXT NOT NULL, source_hash TEXT NOT NULL, PRIMARY KEY(source_system,source_entity,source_id));
-- Protect published document content and confirmed observations; controlled void/supersede allowed.
CREATE TRIGGER immutable_document_content BEFORE UPDATE ON document_revision WHEN OLD.state IN('approved','effective','superseded','withdrawn') AND (NEW.payload_json<>OLD.payload_json OR NEW.document_id<>OLD.document_id OR NEW.version_no<>OLD.version_no) BEGIN SELECT RAISE(ABORT,'immutable document revision'); END;
CREATE TRIGGER document_step_update BEFORE UPDATE ON document_step WHEN EXISTS(SELECT 1 FROM document_revision WHERE id=OLD.revision_id AND state IN('approved','effective','superseded','withdrawn')) BEGIN SELECT RAISE(ABORT,'immutable document steps'); END;
CREATE TRIGGER document_step_delete BEFORE DELETE ON document_step WHEN EXISTS(SELECT 1 FROM document_revision WHERE id=OLD.revision_id AND state IN('approved','effective','superseded','withdrawn')) BEGIN SELECT RAISE(ABORT,'immutable document steps'); END;
CREATE TRIGGER document_step_insert BEFORE INSERT ON document_step WHEN EXISTS(SELECT 1 FROM document_revision WHERE id=NEW.revision_id AND state IN('approved','effective','superseded','withdrawn')) BEGIN SELECT RAISE(ABORT,'immutable document steps'); END;
CREATE TRIGGER audit_response_update BEFORE UPDATE ON audit_response WHEN EXISTS(SELECT 1 FROM audit_session WHERE id=OLD.audit_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable audit response'); END;
CREATE TRIGGER audit_response_delete BEFORE DELETE ON audit_response WHEN EXISTS(SELECT 1 FROM audit_session WHERE id=OLD.audit_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable audit response'); END;
CREATE TRIGGER audit_response_insert BEFORE INSERT ON audit_response WHEN EXISTS(SELECT 1 FROM audit_session WHERE id=NEW.audit_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable audit response'); END;
CREATE TRIGGER assessment_item_update BEFORE UPDATE ON assessment_item WHEN EXISTS(SELECT 1 FROM assessment_session WHERE id=OLD.session_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable assessment'); END;
CREATE TRIGGER assessment_item_delete BEFORE DELETE ON assessment_item WHEN EXISTS(SELECT 1 FROM assessment_session WHERE id=OLD.session_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable assessment'); END;
CREATE TRIGGER assessment_item_insert BEFORE INSERT ON assessment_item WHEN EXISTS(SELECT 1 FROM assessment_session WHERE id=NEW.session_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable assessment'); END;
CREATE TRIGGER criterion_update BEFORE UPDATE ON checklist_criterion WHEN EXISTS(SELECT 1 FROM checklist_version WHERE id=OLD.version_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable checklist'); END;
CREATE TRIGGER criterion_delete BEFORE DELETE ON checklist_criterion WHEN EXISTS(SELECT 1 FROM checklist_version WHERE id=OLD.version_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable checklist'); END;
CREATE TRIGGER criterion_insert BEFORE INSERT ON checklist_criterion WHEN EXISTS(SELECT 1 FROM checklist_version WHERE id=NEW.version_id AND state<>'draft') BEGIN SELECT RAISE(ABORT,'immutable checklist'); END;
CREATE VIEW v_audit_scores AS SELECT a.id,a.version_id,a.mentor_id,a.observed_at,SUM(CASE WHEN r.response='yes' THEN 1 ELSE 0 END) AS passed,SUM(CASE WHEN r.response IN('yes','no') THEN 1 ELSE 0 END) AS observed,COUNT(r.id) AS recorded,(SELECT COUNT(*) FROM checklist_criterion k WHERE k.version_id=a.version_id) AS expected,SUM(CASE WHEN r.response='no' AND c.critical=1 THEN 1 ELSE 0 END) AS critical_failures,100.0*SUM(CASE WHEN r.response='yes' THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN r.response IN('yes','no') THEN 1 ELSE 0 END),0) AS score_pct FROM audit_session a LEFT JOIN audit_response r ON r.audit_id=a.id LEFT JOIN checklist_criterion c ON c.id=r.criterion_id WHERE a.state='final' GROUP BY a.id;
CREATE VIEW v_latest_assessment AS SELECT * FROM (SELECT i.*,s.person_id,s.assessed_at,ROW_NUMBER() OVER(PARTITION BY s.person_id,i.skill_id ORDER BY s.assessed_at DESC,s.id DESC) AS rn FROM assessment_item i JOIN assessment_session s ON s.id=i.session_id WHERE s.state='confirmed' AND i.observation_state='rated') WHERE rn=1;
PRAGMA user_version=1;
COMMIT;
